#ifndef QUAD_DEC_REGS_H
#define QUAD_DEC_REGS_H
#define QUAD_DEC_REGS_ID_OFFSET 0x00u
#define QUAD_DEC_REGS_VERSION_OFFSET 0x04u
#define QUAD_DEC_REGS_DATE_OFFSET 0x08u
#define QUAD_DEC_REGS_ID_VALUE 0x51444543u   /* "QDEC" */
#define QUAD_DEC_REGS_CTRL_OFFSET 0x10u   /* RW */
#define QUAD_DEC_REGS_CTRL_RESET 0x00000001u
#define QUAD_DEC_REGS_CTRL_EN_SHIFT 0u
#define QUAD_DEC_REGS_CTRL_EN_MASK 0x00000001u
#define QUAD_DEC_REGS_CTRL_CLR_POS_SHIFT 1u
#define QUAD_DEC_REGS_CTRL_CLR_POS_MASK 0x00000002u
#define QUAD_DEC_REGS_CTRL_INDEX_CLR_SHIFT 2u
#define QUAD_DEC_REGS_CTRL_INDEX_CLR_MASK 0x00000004u
#define QUAD_DEC_REGS_CTRL_SWAP_SHIFT 3u
#define QUAD_DEC_REGS_CTRL_SWAP_MASK 0x00000008u
#define QUAD_DEC_REGS_CTRL_FILTER_SHIFT 8u
#define QUAD_DEC_REGS_CTRL_FILTER_MASK 0x0000FF00u
#define QUAD_DEC_REGS_POSITION_OFFSET 0x14u   /* CMD */
#define QUAD_DEC_REGS_POSITION_RESET 0x00000000u
#define QUAD_DEC_REGS_VELOCITY_OFFSET 0x18u   /* RO */
#define QUAD_DEC_REGS_VELOCITY_RESET 0x00000000u
#define QUAD_DEC_REGS_WINDOW_OFFSET 0x1Cu   /* RW */
#define QUAD_DEC_REGS_WINDOW_RESET 0x000186A0u
#define QUAD_DEC_REGS_STATUS_OFFSET 0x20u   /* CMD */
#define QUAD_DEC_REGS_STATUS_RESET 0x00000000u
#define QUAD_DEC_REGS_STATUS_DIR_SHIFT 0u
#define QUAD_DEC_REGS_STATUS_DIR_MASK 0x00000001u
#define QUAD_DEC_REGS_STATUS_ERROR_SHIFT 1u
#define QUAD_DEC_REGS_STATUS_ERROR_MASK 0x00000002u
#define QUAD_DEC_REGS_STATUS_INDEX_SHIFT 2u
#define QUAD_DEC_REGS_STATUS_INDEX_MASK 0x00000004u
#define QUAD_DEC_REGS_ERR_COUNT_OFFSET 0x24u   /* RO */
#define QUAD_DEC_REGS_ERR_COUNT_RESET 0x00000000u
#define QUAD_DEC_REGS_INDEX_POS_OFFSET 0x28u   /* RO */
#define QUAD_DEC_REGS_INDEX_POS_RESET 0x00000000u
#endif /* QUAD_DEC_REGS_H */
